package com.autumnharvestc.server.sync;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.nio.file.*;
import java.net.*;
import java.net.http.*;
import java.time.*;
import java.sql.DriverManager;
import java.util.*;
import java.util.concurrent.TimeUnit;
import static org.assertj.core.api.Assertions.*;

/** Owned file H2, stable backend URL, real Node SourceHost/Core, two actual Java processes. */
final class SyncScheduleProcessProbe {
    final ObjectMapper json;final JsonNode node;final Path key;final long nodePid;
    final HttpClient client=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(2)).build();
    Path directory,clock;String base,database,token,projectUrl,sourceId;Process backend;
    SyncScheduleProcessProbe(ObjectMapper json,JsonNode node,Path key,long nodePid){this.json=json;this.node=node;this.key=key;this.nodePid=nodePid;}
    static Path javaExecutable(Path javaHome,String operatingSystem){return javaHome.resolve("bin").resolve(operatingSystem.toLowerCase(Locale.ROOT).startsWith("windows")?"java.exe":"java");}
    JsonNode request(String method,String path,JsonNode input,int status) throws Exception {
        var builder=HttpRequest.newBuilder(URI.create(base+path)).timeout(Duration.ofSeconds(15));if(token!=null)builder.header("Authorization","Bearer "+token);if(input!=null)builder.header("Content-Type","application/json");builder.method(method,input==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(input.toString()));var result=client.send(builder.build(),HttpResponse.BodyHandlers.ofString());assertThat(result.statusCode()).withFailMessage(method+" "+path+": "+result.body()).isEqualTo(status);return result.body().isBlank()?json.nullNode():json.readTree(result.body());
    }
    void start(int number) throws Exception {
        var java=javaExecutable(Path.of(System.getProperty("java.home")),System.getProperty("os.name")).toString();var args=new ArrayList<String>(List.of(java,"-cp",System.getProperty("surefire.test.class.path",System.getProperty("java.class.path")),SyncScheduleProcessBackend.class.getName(),clock.toString(),"--server.address=127.0.0.1","--server.port="+URI.create(base).getPort(),"--spring.datasource.url="+database,"--apicc.server.allow-registration=true","--apicc.scheduler.scan-interval-ms=100","--apicc.scheduler.claim-lease-ms=3000","--apicc.collaboration.runtime.enabled=true","--apicc.collaboration.runtime.base-url="+node.path("url").asText(),"--apicc.collaboration.runtime.secret-file="+node.path("secretFile").asText(),"--apicc.execution.materials.master-key-file="+key));
        backend=new ProcessBuilder(args).redirectErrorStream(true).redirectOutput(directory.resolve("backend-"+number+".log").toFile()).start();long until=System.nanoTime()+TimeUnit.SECONDS.toNanos(18);while(System.nanoTime()<until){if(!backend.isAlive())throw new AssertionError("Owned backend exited: "+Files.readString(directory.resolve("backend-"+number+".log")));try{if(client.send(HttpRequest.newBuilder(URI.create(base+"/api/v1/auth/config")).timeout(Duration.ofSeconds(1)).GET().build(),HttpResponse.BodyHandlers.discarding()).statusCode()==200)return;}catch(java.io.IOException ignored){}Thread.sleep(25);}throw new AssertionError("Owned backend readiness deadline");
    }
    void stop() throws Exception {if(backend==null||!backend.isAlive())return;backend.destroy();if(!backend.waitFor(10,TimeUnit.SECONDS)){backend.destroyForcibly();assertThat(backend.waitFor(5,TimeUnit.SECONDS)).isTrue();}}
    JsonNode successExcept(String old) throws Exception {long until=System.nanoTime()+TimeUnit.SECONDS.toNanos(8);JsonNode last=json.nullNode();while(System.nanoTime()<until){last=request("GET",projectUrl+"/sync/checks?sourceId="+sourceId,null,200).path("latestSuccess");if(!last.isNull()&&!last.path("checkId").asText().equals(old))return last;Thread.sleep(25);}throw new AssertionError("Actual timer did not complete another check; latest="+last);}
    void run() throws Exception {
        directory=Files.createTempDirectory("apicc-t11-os-");clock=directory.resolve("authority-clock.txt");Files.writeString(clock,"2026-11-05T00:00:00Z");database="jdbc:h2:file:"+directory.resolve("database").toString().replace('\\','/')+";DB_CLOSE_ON_EXIT=FALSE";try(var socket=new ServerSocket(0)){base="http://127.0.0.1:"+socket.getLocalPort();}
        try{start(1);long firstPid=backend.pid();String name="t11-os-"+UUID.randomUUID().toString().substring(0,16);var registration=json.createObjectNode().put("username",name).put("password","synthetic-password123").put("displayName",name);request("POST","/api/v1/auth/register",registration,201);token=request("POST","/api/v1/auth/login",json.createObjectNode().put("username",name).put("password","synthetic-password123"),200).path("token").asText();String ws=request("POST","/api/v1/workspaces",json.createObjectNode().put("name","Owned T11 process"),201).path("id").asText();String wsUrl="/api/v1/workspaces/"+ws;String group=request("POST",wsUrl+"/groups",json.createObjectNode().put("name","Owned"),201).path("id").asText();String project=request("POST",wsUrl+"/projects",json.createObjectNode().put("name","Owned").put("groupId",group),201).path("id").asText();projectUrl=wsUrl+"/projects/"+project;
            var delta=json.createObjectNode().put("format","contract-files-v1").put("contractProjectId","00000000-0000-4000-8000-000000000070").put("expectedVersion","0");delta.set("changes",node.path("files"));delta.putArray("deletes");request("PUT",projectUrl+"/assets",delta,200);sourceId=UUID.randomUUID().toString();var source=json.createObjectNode().put("formatVersion",1).put("id",sourceId).put("revision","1").put("moduleId","00000000-0000-4000-8000-000000000071").put("kind","url").put("url",node.path("origin").asText()+"/os-timer");var rule=json.createObjectNode().put("kind","cron").put("expression","0 0 * * * *").put("timeZone","UTC").put("dstOverlap","first");source.set("schedule",json.createObjectNode().put("enabled",false).set("rule",rule));var save=json.createObjectNode().put("formatVersion",1).put("intentId",UUID.randomUUID().toString()).put("expectedSourceRevision","0").put("expectedAssetVersion","1");save.set("source",source);request("POST",projectUrl+"/sync/sources",save,201);
            var check=json.createObjectNode().put("formatVersion",1).put("intentId",UUID.randomUUID().toString()).put("expectedSourceRevision","1").put("expectedAssetVersion","1");request("POST",projectUrl+"/sync/sources/"+sourceId+"/checks",check,202);String warm=successExcept("").path("checkId").asText();var grant=json.createObjectNode().put("formatVersion",1).put("expectedSourceRevision","1").put("expectedGeneration","0").put("enabled",true);grant.set("rule",rule);request("PUT",projectUrl+"/sync/sources/"+sourceId+"/schedule",grant,200);
            Files.writeString(clock,"2026-11-05T01:00:00Z");var first=successExcept(warm);stop();start(2);long secondPid=backend.pid();assertThat(secondPid).isNotEqualTo(firstPid);Thread.sleep(400);var same=request("GET",projectUrl+"/sync/checks?sourceId="+sourceId,null,200).path("latestSuccess");assertThat(same.path("checkId")).isEqualTo(first.path("checkId"));Files.writeString(clock,"2026-11-05T02:00:00Z");var second=successExcept(first.path("checkId").asText());assertThat(second.path("checkId")).isNotEqualTo(first.path("checkId"));assertThat(request("GET",projectUrl+"/assets",null,200).path("version").asText()).isEqualTo("1");stop();
            try(var connection=DriverManager.getConnection(database,"sa","");var statement=connection.createStatement();var rows=statement.executeQuery("SELECT (SELECT COUNT(*) FROM sync_occurrences WHERE project_id="+project+") occurrences,(SELECT COUNT(*) FROM sync_checks WHERE project_id="+project+") checks,(SELECT COUNT(*) FROM sync_candidates WHERE project_id="+project+") candidates,(SELECT COUNT(*) FROM sync_operations WHERE project_id="+project+" AND kind IN ('apply','rollback')) applications")){assertThat(rows.next()).isTrue();assertThat(rows.getInt("occurrences")).isEqualTo(2);assertThat(rows.getInt("checks")).isEqualTo(3);assertThat(rows.getInt("applications")).isZero();var facts=json.createObjectNode().put("backendPidBefore",firstPid).put("backendPidAfter",secondPid).put("nodePid",nodePid).put("backendUrl",base).put("occurrences",rows.getInt("occurrences")).put("checks",rows.getInt("checks")).put("candidates",rows.getInt("candidates")).put("applications",rows.getInt("applications")).put("assetVersion","1").put("firstScheduledCheck",first.path("checkId").asText()).put("secondScheduledCheck",second.path("checkId").asText()).put("testClockInjection","test-only ScheduleTimeSource from owned file").put("desktopConnections",0);Files.writeString(directory.resolve("facts.json"),facts.toPrettyString());System.out.println("T11_OS_PROCESS "+facts);}
        }finally{stop();System.out.println("T11_OS_ARTIFACTS "+directory);}
    }
}
